static void stat_set_property (GObject *object, guint id, const GValue *value, GParamSpec *pspec) { switch (id) { case STAT_PROP_LABEL: awra_stat_bar_set_label (AWRA_STAT_BAR (object), g_value_get_string (value)); break; case STAT_PROP_VALUE: awra_stat_bar_set_value (AWRA_STAT_BAR (object), g_value_get_double (value)); break; case STAT_PROP_MAXIMUM: awra_stat_bar_set_maximum (AWRA_STAT_BAR (object), g_value_get_double (value)); break; case STAT_PROP_SHOW_VALUE: awra_stat_bar_set_show_value (AWRA_STAT_BAR (object), g_value_get_boolean (value)); break; default: G_OBJECT_WARN_INVALID_PROPERTY_ID (object, id, pspec); } }
static void awra_stat_bar_class_init (AwraStatBarClass *klass) { GObjectClass *oc = G_OBJECT_CLASS (klass); GtkWidgetClass *wc = GTK_WIDGET_CLASS (klass); oc->dispose = stat_dispose; oc->finalize = stat_finalize; oc->get_property = stat_get_property; oc->set_property = stat_set_property; wc->snapshot = stat_snapshot; stat_properties[STAT_PROP_LABEL] = g_param_spec_string ("label", NULL, NULL, NULL, G_PARAM_READWRITE | G_PARAM_EXPLICIT_NOTIFY | G_PARAM_STATIC_STRINGS); stat_properties[STAT_PROP_VALUE] = g_param_spec_double ("value", NULL, NULL, 0.0, G_MAXDOUBLE, 0.0, G_PARAM_READWRITE | G_PARAM_EXPLICIT_NOTIFY | G_PARAM_STATIC_STRINGS); stat_properties[STAT_PROP_MAXIMUM] = g_param_spec_double ("maximum", NULL, NULL, 0.0001, G_MAXDOUBLE, 100.0, G_PARAM_READWRITE | G_PARAM_EXPLICIT_NOTIFY | G_PARAM_STATIC_STRINGS); stat_properties[STAT_PROP_SHOW_VALUE] = g_param_spec_boolean ("show-value", NULL, NULL, TRUE, G_PARAM_READWRITE | G_PARAM_EXPLICIT_NOTIFY | G_PARAM_STATIC_STRINGS); g_object_class_install_properties (oc, STAT_N_PROPS, stat_properties); gtk_widget_class_set_layout_manager_type (wc, GTK_TYPE_BIN_LAYOUT); gtk_widget_class_set_css_name (wc, "awrastatbar"); gtk_widget_class_set_accessible_role (wc, GTK_ACCESSIBLE_ROLE_METER); }
static void awra_stat_bar_init (AwraStatBar *self) { GtkWidget *head = gtk_box_new (GTK_ORIENTATION_HORIZONTAL, 0); self->maximum = 100.0; self->show_value = TRUE; self->root = GTK_BOX (gtk_box_new (GTK_ORIENTATION_VERTICAL, 0)); self->label_widget = GTK_LABEL (gtk_label_new (NULL)); self->value_widget = GTK_LABEL (gtk_label_new ("0")); self->progress = AWRA_PROGRESS_BAR (awra_progress_bar_new ()); awra_box_set_spacing (self->root, AWRA_SPACING_XS); gtk_widget_set_hexpand (GTK_WIDGET (self->label_widget), TRUE); gtk_label_set_xalign (self->label_widget, 0.0f); awra_widget_set_typography (GTK_WIDGET (self->value_widget), AWRA_TYPOGRAPHY_MONOSPACE); gtk_box_append (GTK_BOX (head), GTK_WIDGET (self->label_widget)); gtk_box_append (GTK_BOX (head), GTK_WIDGET (self->value_widget)); gtk_box_append (self->root, head); gtk_box_append (self->root, GTK_WIDGET (self->progress)); gtk_widget_set_parent (GTK_WIDGET (self->root), GTK_WIDGET (self)); }
