gboolean awra_stat_bar_get_show_value (AwraStatBar *self) { g_return_val_if_fail (AWRA_IS_STAT_BAR (self), FALSE); return self->show_value; }
void awra_stat_bar_set_show_value (AwraStatBar *self, gboolean show_value) { g_return_if_fail (AWRA_IS_STAT_BAR (self)); show_value = !!show_value; if (self->show_value == show_value) return; self->show_value = show_value; update_stat (self); g_object_notify_by_pspec (G_OBJECT (self), stat_properties[STAT_PROP_SHOW_VALUE]); }

