AwraMetricRow *awra_metadata_group_append (AwraMetadataGroup *self, const char *label, const char *value) { AwraMetricRow *row; g_return_val_if_fail (AWRA_IS_METADATA_GROUP (self), NULL); row = AWRA_METRIC_ROW (awra_metric_row_new (label, value)); awra_metadata_group_append_row (self, row); return row; }
void awra_metadata_group_append_row (AwraMetadataGroup *self, AwraMetricRow *row) { g_return_if_fail (AWRA_IS_METADATA_GROUP (self)); g_return_if_fail (AWRA_IS_METRIC_ROW (row)); g_return_if_fail (gtk_widget_get_parent (GTK_WIDGET (row)) == NULL); g_ptr_array_add (self->rows, row); gtk_box_append (self->root, GTK_WIDGET (row)); }
void awra_metadata_group_remove_row (AwraMetadataGroup *self, AwraMetricRow *row) { guint pos; g_return_if_fail (AWRA_IS_METADATA_GROUP (self)); if (!g_ptr_array_find (self->rows, row, &pos)) return; gtk_box_remove (self->root, GTK_WIDGET (row)); g_ptr_array_remove_index (self->rows, pos); }
guint awra_metadata_group_get_n_rows (AwraMetadataGroup *self) { g_return_val_if_fail (AWRA_IS_METADATA_GROUP (self), 0); return self->rows->len; }
AwraMetricRow *awra_metadata_group_get_row (AwraMetadataGroup *self, guint position) { g_return_val_if_fail (AWRA_IS_METADATA_GROUP (self), NULL); return position < self->rows->len ? g_ptr_array_index (self->rows, position) : NULL; }
